    /** Synchronize explicit provider/bridge availability without pretending it was live-tested. */
    public static function syncFromProviders():int{
        $rows=db()->query('SELECT capability,route_order,provider_key,health_state FROM provider_capability_routes WHERE enabled=1')->fetchAll();$changed=0;
        foreach($rows as $r){$p=(string)$r['provider_key'];$old=(string)$r['health_state'];$available=self::configured($p);$next=$old;
            if(!$available)$next='disabled';elseif($old==='disabled')$next='untested';
            if($next!==$old){db()->prepare('UPDATE provider_capability_routes SET health_state=?,last_error=?,updated_at=NOW() WHERE capability=? AND route_order=?')->execute([$next,$next==='disabled'?'provider_not_configured_or_disabled':null,(string)$r['capability'],(int)$r['route_order']]);$changed++;}
        }
        return $changed;
    }
