    private static function recordDirectImage(int $agentId,int $projectId,int $taskId,string $label,string $prompt,array $raw,string $provider,float $estimatedCost=0):array{
        $path=trim((string)($raw['path']??''));$url=trim((string)($raw['url']??''));if($path===''&&$url==='')throw new RuntimeException('direct_image_reference_missing');
        db()->prepare("INSERT INTO media_requests(project_id,task_id,requested_by_agent_id,media_type,label,prompt_text,provider,state,created_at,completed_at) VALUES (?,?,?,?,?,?,?,'completed',NOW(),NOW())")->execute([$projectId,$taskId?:null,$agentId,'image',$label,$prompt,$provider]);$requestId=(int)db()->lastInsertId();
        db()->prepare("INSERT INTO project_assets(project_id,asset_type,label,source,path_ref,url_ref,status,metadata_json) VALUES (?,?,?,'generated',?,?,'active',?)")->execute([$projectId,'image',$label,$path?:null,$url?:null,j(['media_request_id'=>$requestId,'provider'=>$provider,'model'=>$raw['model']??null,'revised_prompt'=>$raw['revised_prompt']??null])]);$assetId=(int)db()->lastInsertId();
        db()->prepare("UPDATE media_requests SET result_asset_id=? WHERE id=?")->execute([$assetId,$requestId]);
        try{AiBudgetService::record($agentId,$provider,(string)($raw['model']??'image'),'image',0,0,['request_id'=>$requestId,'asset_id'=>$assetId,'estimated_cost_usd'=>$estimatedCost],$taskId?:null,$projectId);}catch(Throwable $e){error_log('PerseBayt direct image budget ledger: '.Security::redactSecrets($e->getMessage(),180));}
        try{Audit::log('system','provider_router','media.generated','project_asset',(string)$assetId,'verified',$projectId,$taskId?:null,['request_id'=>$requestId,'provider'=>$provider,'type'=>'image']);}catch(Throwable){}
        return $raw+['request_id'=>$requestId,'state'=>'completed','asset_id'=>$assetId];
    }
    public static function testRoute(string $cap,int $order):array{$r=self::route($cap,$order);$cap=self::normalizeCapability($cap);$start=microtime(true);try{$p=(string)$r['provider_key'];$ok=match($cap){'browser'=>BrowserAutomationService::configured(),'video','image'=>MediaBridgeClient::configured()||self::configured($p),'web_search'=>self::configured($p),'stt','tts','vision','embeddings','realtime_voice','external_api'=>self::configured($p),default=>self::configured($p)};if(in_array($cap,['text','coding'],true)&&$ok){$agent=(int)AgentService::bySlug('ramy')['id'];$tmp=self::text($agent,'Return OK only.',[['role'=>'user','content'=>'OK']],32,$cap);$ok=trim((string)($tmp['text']??''))!=='';}$lat=(int)round((microtime(true)-$start)*1000);self::markRoute($cap,$order,$ok,$ok?'':'provider_not_configured',$lat);return ['ok'=>$ok,'capability'=>$cap,'provider'=>$p,'latency_ms'=>$lat,'non_billable'=>!in_array($cap,['text','coding'],true)];}catch(Throwable $e){self::markRoute($cap,$order,false,$e->getMessage(),null);throw $e;}}
    private static function openRouterText(array $r,string $inst,array $messages,int $max):array{$payload=['model'=>trim((string)($r['model_key']??''))?:OpenRouterService::preferredModel(),'messages'=>[['role'=>'system','content'=>$inst]],'max_completion_tokens'=>$max,'temperature'=>0.2];foreach($messages as $m)$payload['messages'][]=['role'=>($m['role']??'user')==='assistant'?'assistant':'user','content'=>(string)($m['content']??'')];$raw=OpenRouterService::chat($payload,90,3);return ['text'=>OpenRouterService::messageText($raw),'model'=>$raw['model']??$payload['model'],'input_tokens'=>(int)($raw['usage']['prompt_tokens']??0),'output_tokens'=>(int)($raw['usage']['completion_tokens']??0)];}
    private static function configured(string $p):bool{return match($p){'openrouter'=>OpenRouterService::configured(),'openai'=>OpenAIClient::configured(),'media_bridge'=>MediaBridgeClient::configured(),'browser_automation','browser_bridge'=>BrowserAutomationService::configured(),'generic_call_bridge','call_bridge'=>CallBridgeClient::configured(),'twilio'=>TwilioClient::configured(),'web_search','configured_search'=>WebSearchClient::configured(),default=>self::providerRow($p)};}
